	@Test
	void residualWidthsAndMixedOperandsWorkForBothRootEnumerators() throws Exception {
		for (boolean adjacencyRoot : List.of(false, true)) {
			for (int width : new int[] { 1, 4, 64 }) {
				AtomicInteger callbacks = new AtomicInteger();
				Hooks hooks = new Hooks() {
					private final long[] values = new long[64];

					@Override
					public void residualSlot(int slot, long value) {
						values[slot] = value;
					}

					@Override
					public boolean testResidual(int residual) {
						long neighbor = values[63];
						for (int i = 0; i < width; i++) {
							long expected = switch (i % 4) {
							case 0 -> neighbor;
							case 1 -> neighbor / 10;
							case 2 -> 99L;
							default -> -1L;
							};
							assertEquals(expected, values[63 - i]);
						}
						callbacks.incrementAndGet();
						return neighbor == 11L;
					}
				};
				Operand[] args = new Operand[width];
				int[] slots = new int[width];
				for (int i = 0; i < width; i++) {
					args[i] = switch (i % 4) {
					case 0 -> Operand.col(1);
					case 1 -> Operand.col(0);
					case 2 -> Operand.constant(0);
					default -> Operand.entry(0);
					};
					slots[i] = 63 - i;
				}
				Kernel ir = residualRootShape(adjacencyRoot, List.of(new Probe(0, Operand.col(0), 1),
						new FilterResidual(0, args, slots)), 2);
				String source = LmdbNativeKernelEmitter.emit(ir);
				assertTrue(source.contains(adjacencyRoot ? "roots: while" : "roots: for"));
				var adjacency = new Rows(new long[][] { { 1, 10, 11 }, { 2, 20 } });
				var context = new KernelContext(new NativeAdjacency[] { adjacency }, new long[] { 99 },
						new long[] { -1 }, new long[][] { { 999, 2, 1, 1, -1, 999 } }, new int[] { 1 },
						new int[] { 4 }, hooks, null, new KernelPlan[0], 16, null, null);
				assertEquals(1L, run(ir, context));
				assertEquals(adjacencyRoot ? 3 : 5, callbacks.get());
				assertEquals(1, adjacency.closes);
			}
		}
	}

