	@Test
	void rebindingResetsCompletedOutputAndFallbackState() throws Exception {
		Kernel ir = shape(List.of(new Probe(0, Operand.col(0), 1)), 2);
		var first = new Rows(new long[][] { { 1, 10 }, { 2, 20 } });
		var second = new Rows(new long[][] { { 1, 10 }, { 2, 20 }, { 3, 30 } });
		try (var kernel = compile(ir)) {
			kernel.bind(context(new long[] { 2, 1, 2 }, first));
			assertEquals(2, drain(kernel));
			kernel.bind(context(new long[] { 1, 2, 3 }, second));
			assertEquals(1, first.closes);
			assertEquals(3, drain(kernel));
			kernel.close();
			assertEquals(0, kernel.fill(new long[1], 1));
		}
		assertEquals(1, second.closes);
	}

